-- Add DDIM, introduced in arXiv 2010.02502.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'ddim',
    'DDIM',
    'Denoising Diffusion Implicit Models (DDIM)',
    'Denoising Diffusion Implicit Models (DDIM) are a faster sampling scheme for [diffusion models](/methods/diffusion) that keeps the training objective of [DDPM](/paper/2006.11239) unchanged. DDIM generalizes the Markovian forward process of DDPM to a family of non-Markovian processes with the same marginals, and therefore the same denoising loss. Their reverse processes can skip most timesteps, so a model trained with DDPM can be sampled with far fewer steps. A parameter η interpolates between stochastic DDPM-like sampling (η = 1) and a fully deterministic sampler (η = 0). The deterministic version defines an implicit, ODE-like mapping between noise and images, which lets images be encoded into latents and interpolated meaningfully. In the paper DDIM produced high-quality samples 10× to 50× faster in wall-clock time than DDPM and allowed trading compute for sample quality. DDIM sampling and DDIM inversion became standard tools in latent diffusion systems such as [Stable Diffusion](/methods/stable-diffusion), and in image and video editing, inversion and watermarking.',
    'DDIM, denoising diffusion implicit model',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2020,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2010.02502'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Denoising Diffusion Implicit Models',
    'https://github.com/ermongroup/ddim',
    NULL,
    '[Denoising Diffusion Implicit Models](/paper/2010.02502)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'ddim' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'ddim' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

