INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'ddim citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM ddim_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING ddim_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 77 local citers name the method in title or abstract.
CREATE TEMP TABLE ddim_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'ddim'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        30843, 31401, 31732, 31973, 32612, 32776, 33231, 34138, 35188, 35418, 35719, 35920,
        36619, 36772, 37020, 38475, 39127, 39214, 39494, 39662, 40701, 41863, 41983, 43021,
        43665, 45471, 45574, 46633, 49608, 50813, 51147, 51460, 56944, 57549, 58874, 59160,
        60967, 64001, 68659, 69662, 70522, 70956, 71109, 71172, 72526, 73128, 73651, 74218,
        75542, 75567, 75797, 84961, 85193, 85500, 86476, 87557, 87634, 89221, 89239, 89247,
        89440, 90597, 90770, 90819, 91770, 92216, 94335, 99125, 99541, 99597, 101201, 107175,
        113434, 113701, 116791, 118501, 119347
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM ddim_cited_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'reference' FROM ddim_cited_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

-- 153 papers match the method keywords (same matcher as the
-- daily keyword backfill).
CREATE TEMP TABLE ddim_keyword_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'ddim'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        7635, 8019, 9783, 11179, 11529, 11674, 12189, 12433, 13527, 13632, 13836, 14044,
